private static void moveUnit(Unit unit, float destX, float destY) {
    float f = destX - unit.getBasePoint().x;
    float f2 = destY - unit.getBasePoint().y;
    for (UPoint uPoint : unit.getPoints()) {
        uPoint.x += f;
        uPoint.y += f2;
        if (uPoint.hasSlave()) {
            UPoint basePoint = uPoint.getSlave().getBasePoint();
            uPoint.getSlave().moveTo(basePoint.x + f, basePoint.y + f2);
        }
    }
}
